#include <stdio.h>

static unsigned keys[3];
unsigned answers[3] = {0};

__attribute__((noinline)) int gate(int stage) {
    unsigned want = keys[stage] ^ 165327742u;
    return answers[stage] == want ? 0 : 1;
}

int main(void) {
    unsigned s = 736715u;
    for (int i = 0; i < 3; i++) {
        s = s * 1103515245u + 12345u;
        keys[i] = s;
    }
    for (int i = 0; i < 3; i++) {
        if (gate(i)) return 91 + i;
    }
    return 0;
}
